package at.dergeorg.drawboard.users.domain.users.requires.impl

import at.dergeorg.drawboard.users.domain.users.model.ColorTheme
import at.dergeorg.drawboard.users.domain.users.model.UserProfile
import org.springframework.data.annotation.Id
import org.springframework.data.annotation.Version
import org.springframework.data.relational.core.mapping.Table
import kotlin.time.Instant
import kotlin.uuid.Uuid

/**
 * Row of `users.user_profile`. The id is generated by the application (UUIDv7), so Spring Data cannot tell "new"
 * from it: new profiles are inserted explicitly (R2dbcEntityTemplate.insert), `save()` only ever UPDATEs an existing
 * one - checking and raising [version].
 */
@Table(schema = "users", name = "user_profile")
internal data class UserProfileEntity(
    @Id val id: Uuid,
    val issuer: String,
    val subject: String,
    val username: String,
    val displayName: String?,
    val email: String?,
    val groups: List<String>,
    val firstLoginAt: Instant,
    val lastLoginAt: Instant,
    val theme: ColorTheme,
    /** `null` for a profile that is not stored yet; the insert sets the first version. */
    @Version val version: Long? = null,
)

internal fun UserProfileEntity.toDomain() = UserProfile(
    id = id,
    issuer = issuer,
    subject = subject,
    username = username,
    displayName = displayName,
    email = email,
    groups = groups,
    firstLoginAt = firstLoginAt,
    lastLoginAt = lastLoginAt,
    theme = theme,
    version = checkNotNull(version) { "user profile $id has no version" },
)

/** [version] null = a new profile (insert), otherwise the version the change is based on. */
internal fun UserProfile.toEntity(version: Long?) = UserProfileEntity(
    id = id,
    issuer = issuer,
    subject = subject,
    username = username,
    displayName = displayName,
    email = email,
    groups = groups,
    firstLoginAt = firstLoginAt,
    lastLoginAt = lastLoginAt,
    theme = theme,
    version = version,
)
